#!/usr/bin/env python3
"""Run RLWalk with a deterministic scripted policy command profile.

This is intended for reproducible robot-vs-MuJoCo tests. It avoids joystick
input entirely, starts the policy loop immediately, and writes the command
vector from a ScriptedCommandProfile before each policy inference.
"""
from __future__ import annotations

import argparse
import datetime
import logging
import pickle
import sys
import time

import numpy as np

from pd.common.duck_drive import DuckDrive
from pd.common.puddle_joy import PuddleJoy
from pd.common.scripted_commands import ScriptedCommandProfile
from pd.runtime.RLWalk import RLWalk, _play_rlwalk_sound

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)


class RLWalkScripted(RLWalk):
    def __init__(
        self,
        *args,
        scripted_profile: str = "tiny",
        scripted_scale: float = 1.0,
        scripted_loop: bool = False,
        scripted_file: str | None = None,
        scripted_start_delay_s: float = 0.0,
        stop_at_profile_end: bool = False,
        disable_duck_sense: bool = False,
        **kwargs,
    ):
        super().__init__(*args, **kwargs)
        self.scripted_commands = ScriptedCommandProfile(
            getattr(self.policy, "commands", []),
            profile=scripted_profile,
            scale=float(scripted_scale),
            loop=bool(scripted_loop),
            profile_file=scripted_file,
        )
        self.scripted_start_delay_s = max(0.0, float(scripted_start_delay_s))
        self.stop_at_profile_end = bool(stop_at_profile_end)
        self.disable_duck_sense = bool(disable_duck_sense)
        if self.disable_duck_sense:
            self.duck_sense = None
        logger.info(
            "[RLWalkScripted] profile=%s duration=%.3fs scale=%.3f loop=%s start_delay=%.3fs stop_at_end=%s",
            self.scripted_commands.profile_name,
            self.scripted_commands.duration_s,
            float(scripted_scale),
            bool(scripted_loop),
            self.scripted_start_delay_s,
            self.stop_at_profile_end,
        )

    def _update_scripted_command_for_step(self, elapsed_s: float) -> np.ndarray:
        t_script = max(0.0, float(elapsed_s) - self.scripted_start_delay_s)
        return self.scripted_commands.write_into(self.commands, t_script)

    def run(self):
        """Run the scripted command profile, gated by the normal Power button.

        This intentionally mirrors RLWalk.run(): firmware observations are
        started immediately, but policy inference/actions do not begin until
        the operator presses Power/start.  Once started, joystick axes are not
        used for policy commands; the deterministic ScriptedCommandProfile
        overwrites self.commands before every policy inference.
        """
        PuddleJoy.load_default_controller_definitions()
        controllers = PuddleJoy.discover()
        if not controllers:
            logger.error("No controllers found. Exiting.")
            sys.exit(1)

        for c in controllers:
            c.set_scale(-1.0, 1.0)

        # Use DuckDrive only for button discovery / pressed-event handling and
        # for shared helper state expected by RLWalk.handle_observation.  The
        # scripted profile overwrites the policy command vector whenever the
        # policy is actually running, so joystick axes do not define commands.
        self.duck_drive = DuckDrive(
            policy=self.policy,
            controllers=controllers,
            commands=self.commands,
            config_yaml=self.duck_config,
            engaged=False,
        )

        try:
            logger.info("[RLWalkScripted] starting observation loop; press Power/start to begin scripted policy")
            if self.max_policy_steps is not None:
                logger.warning(
                    "[RLWalkScripted] max_policy_steps=%s: will stop after that many started policy actions",
                    self.max_policy_steps,
                )
            self._policy_stop_sent = False
            self.api.policyStart("default", dt=self.dt)
            self._play_started_sound_once()

            started = False
            t0 = None
            last_obs_time = time.time()
            running = True
            counter = 0

            while running:
                now = time.time()

                # Poll controller(s) so Power/start works just like RLWalk.
                self.duck_drive.update(now)
                status = self.duck_drive.status()
                active = status.get("active", "") if isinstance(status, dict) else ""
                strafe_src = status.get("strafe", "") if isinstance(status, dict) else ""

                # Button handling.  Only Power/start controls scripted-policy
                # start/stop; other buttons are printed for operator feedback.
                for b in self.duck_drive.pop_pressed():
                    print(f"button: {b}")
                    if b == "Select":
                        print("Select")
                    elif b == "Power" or b == "start":
                        if started:
                            running = False
                            print("ENDING SCRIPTED POLICY")
                            self.duck_drive.disengage(reset_commands=True)
                            self._stop_policy_loop("Power button pressed while scripted policy running")
                            break
                        print("STARTING SCRIPTED POLICY")
                        started = bool(self.duck_drive.engage(now, settle_s=0.10))
                        if started:
                            t0 = time.time()
                            self.scripted_commands.write_into(self.commands, 0.0)
                    elif b in ("LS_B", "RS_B", "A", "X", "Y", "LB", "RB"):
                        print(b)
                if not running:
                    break

                msg_type, msg = self.api.receive(blocking=True)
                now = time.time()
                if msg_type is None:
                    elapsed_since_obs = now - last_obs_time
                    if elapsed_since_obs > self.dt * 2:
                        logger.info("[RLWalkScripted] not receiving observations")
                        break
                    continue

                if msg_type != "obs":
                    logger.warning("[RLWalkScripted] unhandled command: %s", msg_type)
                    continue

                last_obs_time = now

                if not self._check_hw_imu_contract(msg):
                    self.duck_drive.disengage(reset_commands=True)
                    self._stop_policy_loop("IMU observation contract mismatch")
                    running = False
                    break

                if not started:
                    sys.stdout.write(
                        f"\r[{counter}][{strafe_src}] {active}: waiting for Power/start to begin scripted profile"
                        "                            "
                    )
                    sys.stdout.flush()
                    counter += 1
                    continue

                elapsed_s = now - (t0 if t0 is not None else now)
                cmd = self._update_scripted_command_for_step(elapsed_s)
                cmd_string = " ".join("{:0.4f}".format(float(x)) for x in cmd)
                sys.stdout.write(
                    f"\r[{counter}][{strafe_src}] {active}: scripted:{elapsed_s:7.3f}s {cmd_string}                            "
                )
                sys.stdout.flush()
                counter += 1

                if not self.handle_observation(msg):
                    break

                if self.policy_step_limit_stop_requested:
                    logger.warning(
                        "[RLWalkScripted] reached max_policy_steps=%s; disengaging and stopping policy loop",
                        self.max_policy_steps,
                    )
                    self.duck_drive.disengage(reset_commands=True)
                    self._stop_policy_loop("max_policy_steps reached")
                    running = False
                    break

                t_script = max(0.0, elapsed_s - self.scripted_start_delay_s)
                if (
                    self.stop_at_profile_end
                    and not self.scripted_commands.loop
                    and t_script >= self.scripted_commands.duration_s
                ):
                    logger.info("[RLWalkScripted] scripted profile ended; disengaging and stopping policy loop")
                    self.duck_drive.disengage(reset_commands=True)
                    self._stop_policy_loop("scripted profile ended")
                    running = False
                    break

        except KeyboardInterrupt:
            pass

        self._stop_policy_loop("RLWalkScripted.run exiting")

        if self.save_obs:
            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            safe_profile = str(self.scripted_commands.profile_name).replace("/", "_").replace(" ", "_")
            fname = f"robot_saved_obs_{ts}-scripted-{safe_profile}.pkl"
            with open(fname, "wb") as f:
                pickle.dump(self.saved_pairs, f)
            print(f"[RLWalkScripted] saved {len(self.saved_pairs)} observations records to {fname}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--onnx_model_path", type=str, required=True, help="ONNX policy (*.onnx) or policy bank YAML (*.yml/*.yaml)")
    parser.add_argument("--duck_control", type=str, default="duck_control.yaml")
    parser.add_argument("--action_scale", type=float, default=1.0)
    parser.add_argument("--command_scale", nargs=3, type=float, default=[1.0, 1.0, 1.0])
    parser.add_argument("--allow_action", action="store_true", help="enable policy actions")
    parser.add_argument("--max_policy_steps", "--policy_steps", dest="max_policy_steps", type=int, default=None)
    parser.add_argument("--save_obs", action="store_true", help="save observations")
    parser.add_argument("--hardcode_original_policy_gains", action="store_true", default=None)
    parser.add_argument("--sounds", action="store_true")
    parser.add_argument("-v", "--verbose", action="store_true")

    parser.add_argument("--scripted_profile", type=str, default="tiny", help="Built-in profile: tiny, step, head")
    parser.add_argument("--scripted_scale", type=float, default=1.0)
    parser.add_argument("--scripted_loop", action="store_true")
    parser.add_argument("--scripted_file", type=str, default=None, help="JSON profile file with segments [{start,end,from,to}]")
    parser.add_argument("--scripted_start_delay_s", type=float, default=0.0)
    parser.add_argument("--stop_at_profile_end", action="store_true")
    parser.add_argument("--disable_duck_sense", action="store_true", help="Do not let DuckSense modify scripted commands")

    try:
        args = parser.parse_args()
    except SystemExit as exc:
        code = exc.code if isinstance(exc.code, int) else (0 if exc.code is None else 1)
        if int(code) != 0 and "--sounds" in sys.argv[1:]:
            _play_rlwalk_sound("error", enabled=True, wait=True)
        raise

    args.action_scale = max(0.0, min(1.0, args.action_scale))
    args.command_scale = [max(0.0, min(1.0, c)) for c in args.command_scale]

    try:
        rl_walk = RLWalkScripted(
            args.onnx_model_path,
            action_scale=args.action_scale,
            command_scale=args.command_scale,
            save_obs=args.save_obs,
            allow_action=args.allow_action,
            max_policy_steps=args.max_policy_steps,
            hardcode_original_policy_gains=args.hardcode_original_policy_gains,
            verbose=args.verbose,
            duck_config=args.duck_control,
            sounds=args.sounds,
            scripted_profile=args.scripted_profile,
            scripted_scale=args.scripted_scale,
            scripted_loop=args.scripted_loop,
            scripted_file=args.scripted_file,
            scripted_start_delay_s=args.scripted_start_delay_s,
            stop_at_profile_end=args.stop_at_profile_end,
            disable_duck_sense=args.disable_duck_sense,
        )
        rl_walk.run()
    except SystemExit as exc:
        code = exc.code if isinstance(exc.code, int) else (0 if exc.code is None else 1)
        if int(code) == 0:
            _play_rlwalk_sound("ended", enabled=args.sounds, wait=True)
        else:
            _play_rlwalk_sound("error", enabled=args.sounds, wait=True)
        raise
    except Exception:
        logger.exception("[RLWalkScripted] failed")
        _play_rlwalk_sound("error", enabled=args.sounds, wait=True)
        sys.exit(1)
    else:
        _play_rlwalk_sound("ended", enabled=args.sounds, wait=True)
